import 'dart:async';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import '../services/bluetooth_chat_service.dart';
import 'chat_screen.dart';
import 'settings_screen.dart';

class HomeScreen extends StatefulWidget { const HomeScreen({super.key}); @override State<HomeScreen> createState() => _HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen> {
  late final BluetoothChatService _service;
  StreamSubscription<List<dynamic>>? _devicesSub; StreamSubscription<String>? _statusSub;
  List<dynamic> _devices = []; String _status = 'اضغط على رمز البلوتوث للبحث عن الأجهزة'; bool _searching = false; bool _searched = false; String _myName = 'مستخدم';
  @override void initState() { super.initState(); _service = BluetoothChatService(); _loadName(); _devicesSub = _service.onDevicesChanged.listen((d) { if (mounted) setState(() => _devices = d); }); _statusSub = _service.onStatusChanged.listen((s) { if (mounted) setState(() { _status = s; _searching = s == 'جارٍ البحث عن الأجهزة...'; }); }); }
  Future<void> _loadName() async { final p = await SharedPreferences.getInstance(); if (mounted) setState(() => _myName = p.getString('profileName') ?? 'مستخدم'); }
  Future<void> _scan() async { if (_searching) return; setState(() { _searching = true; _searched = true; _devices = []; _status = 'جارٍ البحث عن الأجهزة...'; }); try { await _service.scanDevices(); } catch (e) { if (mounted) { setState(() => _status = 'تعذر البحث عن الأجهزة'); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('خطأ في البلوتوث: $e'))); } } finally { if (mounted) setState(() => _searching = false); } }
  Future<void> _connect(dynamic device) async { String name = 'جهاز بلوتوث'; String address = ''; try { name = device.displayName?.toString() ?? name; } catch (_) {} try { address = device.address.toString(); } catch (_) {} if (address.isEmpty) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('تعذر قراءة عنوان الجهاز'))); return; } showDialog<void>(context: context, barrierDismissible: false, builder: (_) => const AlertDialog(content: Row(children: [CircularProgressIndicator(), SizedBox(width: 16), Expanded(child: Text('جارٍ الاتصال بالجهاز...'))]))); try { await _service.connectToDevice(address); if (!mounted) return; Navigator.of(context).pop(); await Navigator.of(context).push(MaterialPageRoute(builder: (_) => ChatScreen(chatService: _service, myUserId: _myName, deviceName: name))); } catch (e) { if (mounted) { Navigator.of(context).pop(); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('فشل الاتصال: $e'))); } } }
  @override void dispose() { _devicesSub?.cancel(); _statusSub?.cancel(); _service.dispose(); super.dispose(); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(backgroundColor: const Color(0xFF075E54), foregroundColor: Colors.white, title: const Text('واتساب بلوتوث'), actions: [IconButton(tooltip: 'بحث', onPressed: _searching ? null : _scan, icon: const Icon(Icons.bluetooth_searching)), IconButton(tooltip: 'الإعدادات', onPressed: () => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const SettingsScreen())), icon: const Icon(Icons.settings))]), body: Column(children: [Container(width: double.infinity, color: const Color(0xFFD7E8E4), padding: const EdgeInsets.all(12), child: Text(_status, textAlign: TextAlign.center)), if (_searching) const LinearProgressIndicator(), Expanded(child: !_searched ? const Center(child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.bluetooth, size: 64, color: Color(0xFF075E54)), SizedBox(height: 12), Text('ابحث عن جهاز قريب لبدء المحادثة')])) : _devices.isEmpty && !_searching ? const Center(child: Padding(padding: EdgeInsets.all(24), child: Text('لم يتم العثور على أجهزة. تحقق من تشغيل البلوتوث وإمكانية اكتشاف الجهاز الآخر.', textAlign: TextAlign.center))) : ListView.builder(itemCount: _devices.length, itemBuilder: (_, i) { final d = _devices[i]; String name = 'جهاز بلوتوث'; String address = ''; try { name = d.displayName?.toString() ?? name; } catch (_) {} try { address = d.address.toString(); } catch (_) {} return ListTile(leading: const CircleAvatar(backgroundColor: Color(0xFF075E54), child: Icon(Icons.bluetooth, color: Colors.white)), title: Text(name), subtitle: Text(address), trailing: const Icon(Icons.chevron_right), onTap: () => _connect(d)); }))]), floatingActionButton: FloatingActionButton(backgroundColor: const Color(0xFF075E54), foregroundColor: Colors.white, onPressed: _searching ? null : _scan, child: const Icon(Icons.bluetooth_searching)));
}